            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            overflow: hidden;
            background:
                radial-gradient(ellipse at 20% 50%, rgba(222, 155, 53, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 50%, rgba(74, 144, 217, 0.06) 0%, transparent 50%),
                var(--bg-dark);
        }

        .hero-bg-pattern {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-image:
                linear-gradient(30deg, rgba(222, 155, 53, 0.03) 12%, transparent 12.5%, transparent 87%, rgba(222, 155, 53, 0.03) 87.5%, rgba(222, 155, 53, 0.03)),
                linear-gradient(150deg, rgba(222, 155, 53, 0.03) 12%, transparent 12.5%, transparent 87%, rgba(222, 155, 53, 0.03) 87.5%, rgba(222, 155, 53, 0.03)),
                linear-gradient(30deg, rgba(222, 155, 53, 0.03) 12%, transparent 12.5%, transparent 87%, rgba(222, 155, 53, 0.03) 87.5%, rgba(222, 155, 53, 0.03)),
                linear-gradient(150deg, rgba(222, 155, 53, 0.03) 12%, transparent 12.5%, transparent 87%, rgba(222, 155, 53, 0.03) 87.5%, rgba(222, 155, 53, 0.03));
            background-size: 80px 140px;
            background-position: 0 0, 0 0, 40px 70px, 40px 70px;
            opacity: 0.5;
        }

        .hero-content {
            position: relative;
            z-index: 2;
            animation: fadeInUp 1s ease;
        }

        .hero-badge {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            background: rgba(222, 155, 53, 0.1);
            border: 1px solid rgba(222, 155, 53, 0.3);
            padding: 8px 20px;
            border-radius: 50px;
            font-size: 0.85rem;
            font-weight: 600;
            color: var(--primary);
            margin-bottom: 30px;
            animation: fadeIn 1s ease 0.3s both;
        }

        .hero-badge .dot {
            width: 8px;
            height: 8px;
            background: var(--green);
            border-radius: 50%;
            animation: pulse 2s infinite;
        }

        .hero h1 {
            font-size: clamp(3rem, 8vw, 6rem);
            font-weight: 900;
            line-height: 1.05;
            color: var(--text-light);
            text-transform: uppercase;
            letter-spacing: 3px;
            margin-bottom: 10px;
            animation: fadeInUp 1s ease 0.2s both;
        }

        .hero h1 .highlight {
            background: var(--gradient-primary);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .hero-subtitle {
            font-size: clamp(1rem, 2.5vw, 1.3rem);
            color: var(--text-muted);
            max-width: 600px;
            margin: 20px auto 40px;
            line-height: 1.8;
            animation: fadeInUp 1s ease 0.4s both;
        }

        .hero-buttons {
            display: flex;
            gap: 20px;
            justify-content: center;
            flex-wrap: wrap;
            animation: fadeInUp 1s ease 0.6s both;
        }

        .btn {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 15px 35px;
            border-radius: 8px;
            font-size: 1rem;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            cursor: pointer;
            transition: all 0.3s ease;
            border: none;
        }

        .btn-primary {
            background: var(--gradient-primary);
            color: #000;
            box-shadow: 0 4px 20px rgba(222, 155, 53, 0.3);
        }

        .btn-primary:hover {
            transform: translateY(-3px);
            box-shadow: 0 8px 35px rgba(222, 155, 53, 0.5);
        }

        .btn-secondary {
            background: transparent;
            color: var(--text-light);
            border: 2px solid rgba(255, 255, 255, 0.2);
        }

        .btn-secondary:hover {
            border-color: var(--primary);
            color: var(--primary);
            transform: translateY(-3px);
        }

        .hero-stats {
            display: flex;
            justify-content: center;
            gap: 60px;
            margin-top: 60px;
            animation: fadeInUp 1s ease 0.8s both;
        }

        .hero-stat {
            text-align: center;
        }

        .hero-stat-value {
            font-size: 2.5rem;
            font-weight: 900;
            color: var(--primary);
            line-height: 1;
        }

        .hero-stat-label {
            font-size: 0.85rem;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-top: 8px;
        }

        .hero-scroll-indicator {
            position: absolute;
            bottom: 30px;
            left: 50%;
            transform: translateX(-50%);
            animation: float 3s ease-in-out infinite;
            z-index: 2;
        }

        .hero-scroll-indicator a {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 8px;
            color: var(--text-muted);
            font-size: 0.75rem;
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        .scroll-arrow {
            width: 24px;
            height: 24px;
            border-right: 2px solid var(--primary);
            border-bottom: 2px solid var(--primary);
            transform: rotate(45deg);
        }

        /* ===== SECTION STYLES ===== */
        section {
            padding: 100px 0;
            position: relative;
            z-index: 1;
        }

        .section-header {
            text-align: center;
            margin-bottom: 60px;
        }

        .section-tag {
            display: inline-block;
            background: rgba(222, 155, 53, 0.1);
            border: 1px solid rgba(222, 155, 53, 0.2);
            color: var(--primary);
            padding: 6px 16px;
            border-radius: 50px;
            font-size: 0.8rem;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 2px;
            margin-bottom: 15px;
        }

        .section-header h2 {
            font-size: clamp(2rem, 4vw, 3rem);
            font-weight: 800;
            color: var(--text-light);
            text-transform: uppercase;
            letter-spacing: 2px;
        }

        .section-header h2 .highlight {
            background: var(--gradient-primary);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .section-header p {
            color: var(--text-muted);
            max-width: 600px;
            margin: 15px auto 0;
            font-size: 1.05rem;
        }

